$(document).ready(() => {
  $(document).ajaxStart(() => {
    $("#loadingOverlay").show().attr("aria-hidden", "false");
  });
  $(document).ajaxStop(() => {
    $("#loadingOverlay").hide().attr("aria-hidden", "true");
  });
  fetch("/html/common/loadingDialog.html").then((r) => {
    if (!r.ok) throw new Error("Failed to load loading dialog");
    return r.text();
  }).then((html) => {
    const container = document.getElementById("loadingDialog");
    if (container) {
      container.innerHTML = html;
    } else {
      console.error("Could not find element with id 'loadingDialog' in the DOM.");
    }
  }).catch((err) => console.error(err));
});
