        $pnModalPaymentAmountDueWithSchool = $("#pnModalPaymentAmountDueWithSchool");
        $pnModalPaymentAmountDueWithReinstatement = $("#pnModalPaymentAmountDueWithReinstatement");
        $pnPaymentAmountDueWithReinstatementAndSchool = $("#pnModalPaymentAmountDueWithReinstatementAndSchool");
        $lblCourtLateFee = $("#lblCourtLateFee");
        if (recordModel.courtLateFeeAmountDue === "0.00") {
          $lblCourtLateFee.attr("hidden", true);
        } else {
          $lblCourtLateFee.attr("hidden", false);
          $lblCourtLateFee.text("A " + recordModel.courtLateFeeAmountDue + " court late fee was added to the total due");
        }
        if (recordModel.isSchoolAvailable === "Y") {
          $pnModalPaymentAmountDueWithSchool.attr("hidden", false);
        } else {
          $pnModalPaymentAmountDueWithSchool.attr("hidden", true);
        }
        if (recordModel.isEligibleToReinstate === "Y") {
          $pnModalPaymentAmountDueWithReinstatement.attr("hidden", false);
        } else {
          $pnModalPaymentAmountDueWithReinstatement.attr("hidden", true);
        }
        if (recordModel.isSchoolAvailable === "Y" & recordModel.isEligibleToReinstate === "Y") {
          $pnPaymentAmountDueWithReinstatementAndSchool.attr("hidden", false);
        } else {
          $pnPaymentAmountDueWithReinstatementAndSchool.attr("hidden", true);
        }
        $lblModalPaymentAmountDue = $("#lblModalPaymentAmountDue");
        $lblModalPaymentAmountDueWithSchool = $("#lblModalPaymentAmountDueWithSchool");
        $lblModalPaymentAmountDueWithReinstatement = $("#lblModalPaymentAmountDueWithReinstatement");
        $lblModalPaymentAmountDueWithReinstatementAndSchool = $("#lblModalPaymentAmountDueWithReinstatementAndSchool");
        $lblModalPaymentAmountDue.text(recordModel.amountDue);
        $lblModalPaymentAmountDueWithSchool.text(recordModel.amountDueWithSchool);
        $lblModalPaymentAmountDueWithReinstatement.text(recordModel.amountDueForReinstate);
        $lblModalPaymentAmountDueWithReinstatementAndSchool.text(recordModel.amountDueForReinstateWithSchool);
        $("#divCasePaymentEmbedded").replaceWith($("#divCasePaymentSection .modal-content").html());
        $("#btnCasePayment").prop("hidden", true);
