    if (searchResultsRow === null) {
      return rowDetail;
    }
    if (trafficCase || searchResultsRow.caseNumber.indexOf("-CM-") !== -1 || searchResultsRow.caseNumber.indexOf("-cm-") !== -1) {
      rowDetail = '<div cellpadding="3" cellspacing="0" border="0">';
      rowDetail = rowDetail + "<div class='row'>";
      rowDetail = rowDetail + "<div id='tdDetail' class='col-lg-offset-1 col-md-offset-1 col-sm-offset-1 col-lg-11 col-md-11 col-sm-11'>";
      rowDetail = rowDetail + "<div class=''><h5 class='text-left text-primary'> Actions for Citation: <label id='lblCitationNumber'>" + searchResultsRow.citationNumber + "</label><label id='lblCaseID' class='hidden'>" + searchResultsRow.caseID + "</label><label id='lblCitationID' class='hidden'>" + searchResultsRow.citationID + "</label><label id='lblCaseNumber' class='hidden'>" + searchResultsRow.caseNumber + "</label></h5></div>";
    }
