    var filterInput = $(".dataTables_filter input").unbind();
    var searchButton = $('<button type="button">Search</button>');
    var clearButton = $('<button type="button">Clear</button>');
    $btnSearch = searchButton.click(function() {
      table.search(filterInput.val()).draw();
    });
    $btnSearchClear = clearButton.click(function() {
      filterInput.val("");
      searchButton.click();
    });
    $(document).keypress(function(event) {
      if (event.which === 13) {
        searchButton.click();
      }
    });
    $(".dataTables_filter").append(searchButton, clearButton);
    table.on("draw", function() {
      if (searchData.SendParameters.draw === 1) {
        searchData.SendParameters.draw = 0;
        filterInput.val("");
        searchButton.click();
      }
      $('[data-toggle="tooltip"]').tooltip();
    });
    $mycasesdataTb.on("click", "button.details", handleMycasesdataTbClick);
    $mycasesdataTbAction.on("click", "button.action", handleMyCaseActionClick);
