  var validateCaptcha = function fnValidateCaptcha() {
    var captchaResponse = grecaptcha.getResponse();
    if (captchaResponse.length === 0) {
      return false;
    } else {
      var ajax;
      $captchaModal.modal("hide");
      if ($captchaProcess.val() === "Redaction") {
        var redactionRequest = getRedactionRequestModel();
        redactionRequest.RequestorIP = captchaResponse;
        redactionRequest.DocumentID = $docviewDocId.val();
        redactionRequest.DocumentVersionID = $docviewDocVersionId.val();
        redactionRequest.RequestorToken = $docviewToken.val();
        redactionRequest.RequestorGuid = $docviewGuid.val();
        ajax = dataService.redactionCaptchaValidation(redactionRequest);
        ajax.done(function() {
          $redactionRequestedModal.modal("show");
          return true;
        }).fail(function(xhr, textStatus, errorThrown) {
          hover.msg.title = "Redaction Error";
          hover.msg.message = "Error:" + errorThrown + "<br/>textStatus:" + textStatus + "<br/>xhr:" + xhr;
          hover.sendMessage(hover.msg);
          return false;
        }).always(function() {
        });
        $this.replaceWith(
          "<label style='border: 0; background-color: Transparent;' data-toggle='tooltip' title='Image Undergoing Redaction Process'><img src='/images/icon-inspector32.png' class='docimg'></label>"
        );
      } else if ($captchaProcess.val() === "FileRequest") {
        var fileViewingRequestmodel = {
          CaseNumber: $lblCaseNumber.text(),
          CaseId: $lblCaseID.text(),
          NodeID: $lblNodeID.text(),
          EventCode: $lblEventCode.text(),
          RequestorID: "",
          RequestorName: $fileRequesterName.val(),
          RequestorEmail: $fileRequesterEmail.val(),
          RequestedDate: "",
          ProcessedDate: captchaResponse
          // used as placeholder, this will be overridden by the process
        };
        ajax = dataService.fileViewingRequestInsert(fileViewingRequestmodel);
        ajax.done(function() {
          var searchSecurity = hover.getSearchSecurityModel();
          loadCaseEvent(searchSecurity);
          handleFileLocationsRequest(searchSecurity);
          hover.msg.title = "Document Viewing Request!";
          hover.msg.message = "<p>We have received your request to view this court file. </p><br/><p>It will take approximately 3 business days for us to process your request. </p><br/><p>We will notify you when the court file is ready to be viewed at the email address provided.</p>";
          $("#dialog").html(hover.msg.message);
          hover.sendMessage(hover.msg);
          return false;
        });
        ajax.fail(function(xhr, textStatus, errorThrown) {
          hover.msg.title = "File Viewing Request Error!";
          hover.msg.message = "<p>" + errorThrown + "</p>";
          $("#dialog").html(hover.msg.message);
          hover.sendMessage(hover.msg);
          return false;
        });
        ajax.always(function() {
        });
      }
    }
    return true;
  };
