  var sendToRedaction = function fnSendToRedaction(eventViewModel) {
    var redactionRequest = getRedactionRequestModel();
    var userInfo2 = hover.getUserInformationModel();
    if (eventViewModel.documentAppliedSecurity === "X") {
      $eventsTable.off();
      $docviewDocId.val(eventViewModel.documentID);
      $docviewDocVersionId.val(eventViewModel.documentVersionID);
      $docviewToken.val(userInfo2.AccessToken);
      $docviewGuid.val(userInfo2.RequestorGuid);
      redactionRequest.DocumentID = eventViewModel.documentID;
      redactionRequest.DocumentVersionID = eventViewModel.documentVersionID;
      redactionRequest.CaseNumber = eventViewModel.caseNumber;
      if (userInfo2.Roles.length === 0 || userInfo2.Roles.find((item) => item.name === "GeneralPublic")) {
        $captchaProcess.val("Redaction");
        $captchaModalContinue.off("click", validateCaptcha);
        $captchaModalContinue.on("click", validateCaptcha);
        $captchaModal.modal("show");
        setTimeout(function() {
          createRecaptcha();
        }, 100);
      } else {
        insertRedactionRequest(redactionRequest);
      }
    } else {
      $docviewDocId.val(eventViewModel.documentID);
      $docviewDocVersionId.val(eventViewModel.documentVersionID);
      $docviewToken.val(userInfo2.AccessToken);
      $docviewGuid.val(userInfo2.RequestorGuid);
      $docview.attr("action", docViewUrl);
      $docview.submit();
    }
  };
