  function loadPaymentPlan(financialData) {
    if (financialData.paymentPlanID === 0) {
      $("#financialTabs li:nth-child(5)").hide();
    } else {
      $ppPartyName.text(financialData.partyName);
      $ppPartyType.text(financialData.partyType);
      $("#financialTabs li:nth-child(5)").show();
      var payments = parseFloat(financialData.paymentAmount, 10).toFixed(2).replace(/(\d)(?=(\d{3})+\.)/g, "$1,");
      var amount = parseFloat(financialData.numberOfPayments, 10).toFixed(2).replace(/(\d)(?=(\d{3})+\.)/g, "$1,");
      $paymentPlanID.val(financialData.paymentPlanID);
      $installmentAmount.val(hover.formatCurrency((payments * amount).toFixed(2)));
      $numberOfPayments.val(financialData.numberOfPayments);
      $frequency.val(financialData.frequency);
      $paymentAmount.val(hover.formatCurrency(financialData.paymentAmount));
      $startDate.val(financialData.startDate);
      $payOffDate.val(financialData.payOffDate);
      $totalDue.val(hover.formatCurrency(financialData.totalDue));
      $balance.val(hover.formatCurrency(financialData.balance));
    }
  }
  function createSummaryDetail(financialData) {
    $("#financialDetails li:nth-child(1)").hide();
    $("#financialDetails li:nth-child(2)").hide();
    $("#financialDetails li:nth-child(3)").hide();
    $("#financialDetails li:nth-child(4)").hide();
    $("#financialDetails li:nth-child(5)").hide();
    if (financialData.financialFees && financialData.financialFees.length > 0) {
      $("#financialDetails li:nth-child(1)").show();
      $("a[href='#financialFee]'").tab("show");
      loadFinancialFees(financialData.financialFees);
    }
    if (financialData.financialFeeTransactions && financialData.financialFeeTransactions.length > 0) {
      $("#financialDetails li:nth-child(2)").show();
      loadFinancialFeeTransactions(financialData.financialFeeTransactions);
    }
    if (financialData.financialRegistries && financialData.financialRegistries.length > 0) {
      $("#financialDetails li:nth-child(3)").show();
      $("a[href='#financialRegistry']").tab("show");
      loadFinancialRegistry(financialData.financialRegistries);
    }
    if (financialData.financialRegistryTransactions && financialData.financialRegistryTransactions.length > 0) {
      $("#financialDetails li:nth-child(4)").show();
      loadFinancialRegistryTransactions(financialData.financialRegistryTransactions);
    }
    if (financialData.paymentPlanID > 0) {
      $("#financialDetails li:nth-child(5)").show();
      loadPaymentPlan(financialData);
    }
  }
  function getCaseFinancialDetailByCaseIDPartyIDPartyTypeID(data) {
    var ajax = dataService.caseFinancialDetailByCaseIDPartyIDPartyTypeID(data);
    ajax.done(function(financialData) {
      if (!financialData[0] || !financialData[0].caseNumber || financialData[0].caseNumber === "") {
        alert("Case Not Found!");
      } else {
        return createSummaryDetail(financialData[0]);
      }
      return false;
    });
    ajax.fail(function(xhr, textStatus, errorThrown) {
      alert(errorThrown);
      return false;
    });
    ajax.always(function() {
    });
  }
  var handleFinancialSummaryTableClick = function fnFinancialSummaryTableClick() {
    $(".panel-collapse").collapse("hide");
    if (!financialSummaryTable) {
      return;
    }
    var tr = $(this).closest("tr");
    var row = financialSummaryTable.row(tr);
    var financialSummaryRow = row.data();
    if (!financialSummaryRow)
      return;
    if (row.child.isShown()) {
      row.child.hide();
      tr.removeClass("shown");
    } else {
      tr.addClass("shown");
      var tableLength = financialSummaryTable.data().length;
      for (var i = 0; i < tableLength; i++) {
        var child = financialSummaryTable.row(i).child;
        child.remove();
      }
      var rowDetail = "";
      rowDetail += "<div id='finance' class='col-lg-offset-1 col-md-offset-1 col-sm-offset-1 col-lg-11 col-md-11 col-sm-11'>";
      row.child(rowDetail).show();
      var extFile = baseWebUrl + "financialTransaction.html #financialDetails";
      $finance = $("#finance");
      $finance.load(extFile, function(response2, status, xhr) {
        if (status === "error") {
          var msg = "Sorry but there was an error: ";
          $error.html(msg + xhr.status + " " + xhr.statusText);
        }
        $ffPartyName = $("#ffPartyName");
        $ffPartyType = $("#ffPartyType");
        $financialFeeSummaryTable = $("#financialFeeSummaryTable");
        $financialFeeTable = $("#financialFeeTable");
        $fftPartyName = $("#fftPartyName");
        $fftPartyType = $("#fftPartyType");
        $financialFeeTransactionsTable = $("#financialFeeTransactionsTable");
        $frPartyName = $("#frPartyName");
        $frPartyType = $("#frPartyType");
        $financialRegistrydata = $("#financialRegistrydata");
        $frtPartyName = $("#frtPartyName");
        $frtPartyType = $("#frtPartyType");
        $financialRegistryTransactionTable = $("#financialRegistryTransactionTable");
        $ppPartyName = $("#ppPartyName");
        $ppPartyType = $("#ppPartyType");
        $paymentPlanID = $("#paymentPlanID");
        $installmentAmount = $("#installmentAmount");
        $numberOfPayments = $("#numberOfPayments");
        $frequency = $("#frequency");
        $paymentAmount = $("#paymentAmount");
        $startDate = $("#startDate");
        $payOffDate = $("#payOffDate");
        $totalDue = $("#totalDue");
        $balance = $("#balance");
        getCaseFinancialDetailByCaseIDPartyIDPartyTypeID(financialSummaryRow);
      });
    }
  };
  function formatFinancialRowDetails(financialViewModel) {
    var rowDetail = "";
    if (financialViewModel) {
      return rowDetail;
    }
    if (financialViewModel.financialTransaction.length === 0) {
      return rowDetail;
    }
    rowDetail = "<table cellpadding='5' cellspacing='0' border='0' style='padding-left:50px;'>";
    for (var i = 0; i < financialViewModel.financialTransaction.length; i++) {
      rowDetail = rowDetail + "<tr>";
      rowDetail = rowDetail + "<td>" + financialViewModel.financialTransaction[i].transactionDate + "</td>";
      rowDetail = rowDetail + "<td>" + financialViewModel.financialTransaction[i].transactionDesc + "</td>";
      rowDetail = rowDetail + "<td>" + financialViewModel.financialTransaction[i].transactionReceipt + "</td>";
      rowDetail = rowDetail + "<td>" + financialViewModel.financialTransaction[i].transactionPayer + "</td>";
      rowDetail = rowDetail + "<td>" + hover.formatCurrency(financialViewModel.financialTransaction[i].transactionAmount) + "</td>";
      rowDetail = rowDetail + "</tr>";
    }
    rowDetail = rowDetail + "</table>";
    return rowDetail;
  }
  function createDisbursementDetail(row) {
    if (row.length === 0) {
      return false;
    }
    var rowDetail = "<table cellpadding='5' cellspacing='0' border='0' style='padding-left:50px;'>";
    for (var i = 0; i < row.length; i++) {
      rowDetail = rowDetail + "<tr>";
      if (row.disbursementDescription !== "") {
        rowDetail = rowDetail + "<td>" + row.disbursementDescription + "</td>";
      }
      if (row.transactionCutOffDate !== "") {
        rowDetail = rowDetail + "<td>Cut Off:" + row.transactionCutOffDate + "</td>";
      }
      if (row.disbursementCheck !== "0") {
        rowDetail = rowDetail + "<td>CHECK No:" + row.disbursementCheck + "</td>";
      }
      if (row.disbursementPayTo !== "") {
        rowDetail = rowDetail + "<td>Pay To:" + row.disbursementPayTo + "</td>";
      }
      rowDetail = rowDetail + "</tr>";
    }
    rowDetail = rowDetail + "</table>";
    return rowDetail;
  }
