  function setLocation(radioValue) {
    $selectedSearchType.val(radioValue);
    switch (radioValue) {
      case "RecordCenter":
        $officeLocation.text(" Tampa ");
        $lblEventCode.text("FTRCCSC");
        break;
      case "Brandon":
        $officeLocation.text(" Brandon ");
        $lblEventCode.text("FTRCBRC");
        break;
      case "PlantCity":
        $officeLocation.text(" Plant City ");
        $lblEventCode.text("FTRCPC");
        break;
      case "SouthShore":
        $officeLocation.text(" SouthShore ");
        $lblEventCode.text("FTRCSS");
        break;
      default:
        $officeLocation.text(" Tampa ");
        $lblEventCode.text("FTRCCSC");
    }
    $fileRequesterName.focus();
  }
  function loadFileViewingRequest(fileLocation) {
    $fileTransferring.text("");
    if (fileLocation.length === 0) {
      $tabCaseFileLocation.hide();
      $openFileLocation.attr("hidden", true);
      return;
    }
    $currentFileLocation.text(fileLocation[0].locDesc);
    $tabCaseFileLocation.show();
    $openFileLocation.attr("hidden", false);
    var text = fileLocation[0].caseNumber + " " + fileLocation[0].style;
    $lblDescription.text(text);
    $lblCaseNumber.text(fileLocation[0].caseNumber);
    $lblCaseID.text(fileLocation[0].caseID);
    $lblNodeID.text(fileLocation[0].nodeID);
    $lblEventCode.text("FTRCCSC");
    var userInfo2 = hover.getUserInformationModel();
    if (userInfo2.Email) {
      $fileRequesterEmail.val(userInfo2.Email);
      $fileRequesterEmail.prop("disabled", true);
    } else {
      $fileRequesterEmail.prop("disabled", false);
    }
    var handleSelectLocation = function fnSelectLocation(selected) {
      setLocation(selected.currentTarget.defaultValue);
    };
    $btnSelectLocation.on("change", handleSelectLocation);
    $orderPaperfileViewing.on("click", handleOrderPaperFileViewing);
  }
  var resetSearch = function fnResetSearch(searchMode) {
    var searchSecurityModel = {
      UserName: sessionStorage.getItem("userName"),
      BarNumber: sessionStorage.getItem("barNumber"),
      //-------------------
      //SearchType: 'HPC', Get High Profile cases
      //SearchType: 'ByCase',
      //SearchType: 'ByParty',
      //SearchType: 'ByCitation',
      //SearchType: 'ByAttorney',
      //SearchType: 'ByDateFiled',
      SearchType: searchMode,
      //-------------------
      CaseNumber: "",
      CrossReferenceNumber: "",
      LastName: "",
      FirstName: "",
      MiddleName: "",
      DateOfBirth: "",
      CitationNumber: "",
      //-------------------
      // CaseStatus
      //-------------------
      //CaseStatus: 'A', // All
      //CaseStatus: 'O', // Open & Reopen
      //CaseStatus: 'C', // Close
      CaseStatus: "A",
      //-------------------
      CaseCategory: "",
      CaseType: "",
      DateFiledFrom: "",
      DateFiledTo: "",
      ErrorFound: false,
      RequestorToken: "",
      RequestorGuid: "",
      NewSearch: 1
    };
    var userInfo2 = hover.getUserInformationModel();
    searchSecurityModel.UserName = userInfo2.UserName;
    searchSecurityModel.BarNumber = userInfo2.BarNumber;
    searchSecurityModel.RequestorToken = userInfo2.AccessToken;
    searchSecurityModel.RequestorGuid = userInfo2.RequestorGuid;
    return searchSecurityModel;
  };
