  var loadCaseInformationExtended = function fnLoadCaseInformationExtended(data) {
    $amountDue1.text(data.amountDue);
    $amountDueDate1.text(data.amountDueDate);
    if (data.caseNumber.indexOf("TR") >= 0) {
      $pAmountDueForReinstate.attr("hidden", false);
      $amountDueForReinstate.text(data.amountDueForReinstate);
      $amountDueForReinstateWithSchool.text(data.amountDueForReinstateWithSchool);
      $amountDueForReinstateWithSchoolWithServiceFee.text(data.amountDueForReinstateWithSchoolWithServiceFee);
      $amountDueForReinstateWithServiceFee.text(data.amountDueForReinstateWithServiceFee);
      $amountDueWithSchool.text(data.amountDueWithSchool);
      $amountDueWithSchoolWithServiceFee.text(data.amountDueWithSchoolWithServiceFee);
      $amountDueWithServiceFee.text(data.amountDueWithServiceFee);
      $reinstatementFee.text(data.reinstatementFee);
      $citationID.text(data.citationID);
      $citationNumber1.text(data.citationNumber);
      $dmvlsD6.text(data.dmvIsD6);
      $driverDOB.text(data.driverDOB);
      $driverLicenseNumber.text(data.driverLicenseNumber);
      $driverLicenseState.text(data.driverLicenseState);
      $complianceNeeded.text(data.complianceNeeded);
      if (data.driverDOB !== "" | data.driverLicenseNumber !== "" | data.driverLicenseState !== "") {
        $licenseGrp.attr("hidden", false);
        if (data.driverDOB !== "") {
          $pDriverDOB.attr("hidden", false);
          $pDriverDOB.val(data.driverDOB);
        }
        if (data.driverLicenseNumber !== "") {
          $pDriverLicenseNumber.attr("hidden", false);
          $pDriverLicenseNumber.val(data.driverLicenseNumber);
        }
        if (data.driverLicenseState !== "") {
          $pDriverLicenseState.attr("hidden", false);
          $pDriverLicenseState.val(data.driverLicenseState);
        }
      } else {
        $licenseGrp.attr("hidden", true);
      }
      $isEligibleToReinstate.text(data.isEligibleToReinstate);
      if (data.isEligibleToReinstate !== "Y") {
        $pAmountDueForReinstate.attr("hidden", true);
        $pAmountDueForReinstateWithSchool.attr("hidden", true);
        $pAmountDueForReinstateWithServiceFee.attr("hidden", true);
        $pAmountDueForReinstateWithSchoolWithServiceFee.attr("hidden", true);
      } else {
        $pAmountDueForReinstate.attr("hidden", false);
        $pAmountDueForReinstateWithServiceFee.attr("hidden", false);
        $pAmountDueForReinstateWithSchool.attr("hidden", false);
        $pAmountDueForReinstateWithSchoolWithServiceFee.attr("hidden", false);
        $isEligibleForSchool.text(data.isEligibleForSchool);
        $isEligibleToGetCourtDate.text(data.isEligibleToGetCourtDate);
        $isEligibleToPay.text(data.isEligibleToPay);
        $isSchoolAvailable.text(data.isSchoolAvailable);
        $isSchoolElected.text(data.isSchoolElected);
        $isSetCourtDateAvailable.text(data.isSetCourtDateAvailable);
        $licenseSuspended.text(data.licenseSuspended);
        $flags.append(
          "<div class='col-lg-4 col-md-4 col-sm-4'><span class='list-group-item'>Is D6: <i class='text-danger'>" + data.isD6ed + "</i></span><span class='list-group-item'>Is License Suspended: <i class='text-danger'>" + data.licenseSuspended + "</i></span><span class='list-group-item'>Is Eligible To Reinstate: <i class='text-danger'>" + data.isEligibleToReinstate + "</i></span><span class='list-group-item'>Is Eligible To Pay: <i class='text-danger'>" + data.isEligibleToPay + "</i></span></div><div class='col-lg-4 col-md-4 col-sm-4'><span class='list-group-item'>Is Eligible For School: <i class='text-danger'>" + data.isEligibleForSchool + "</i></span><span class='list-group-item'>Is School Available: <i class='text-danger'>" + data.isSchoolAvailable + "</i></span><span class='list-group-item'>Is School Elected: <i class='text-danger'>" + data.isSchoolElected + "</i></span></div><div class='col-lg-4 col-md-4 col-sm-4'><span class='list-group-item'>Is Eligible To Get Court Date: <i class='text-danger'>" + data.isEligibleToGetCourtDate + "</i></span><span class='list-group-item'>Is Eligible To Set Court Date: <i class='text-danger'>" + data.isSetCourtDateAvailable + "</i></span><span class='list-group-item'>Compliance Needed: <i class='text-danger'>" + data.complianceNeeded + "</i></span></div>"
        );
      }
    } else {
      $licenseGrp.attr("hidden", true);
    }
    $amountReceived.text(data.amountReceived);
    $caseDivision.text(data.caseDivision);
    $caseID.text(data.caseID);
    $caseNumber1.text(data.caseNumber1);
    data.charges = data.charges.substr(3);
    var chargeList = data.charges.split(",,,").join("<br/>");
    $charges1.append(chargeList);
    var collectionAgency = "";
    if (data.collectionsAgencyWavName === "PENNCREDIT") {
      collectionAgency = data.collectionsAgencyWavName + " telephone: 1-800-900-1380";
    } else if (data.collectionsAgencyWavName === "LINEBARGER") {
      collectionAgency = data.collectionsAgencyWavName + " telephone: 1-866-234-9790";
    }
    $collectionsAgencyWavName.text(collectionAgency);
    var collectionStatus = "";
    switch (data.collectionStatus) {
      case "OK":
        collectionStatus = "OK";
        break;
      case "OD":
        collectionStatus = "Overdue";
        break;
      case "CA":
        collectionStatus = "In Collections";
        break;
    }
    $collectionStatus.text(collectionStatus);
    var courtAddress = "";
    if (data.courtLocationWavName !== "") {
      switch (data.courtLocationWavName) {
        case "TampaCourtZ2":
          courtAddress = "419 Pierce Street, Tampa 33602";
          break;
        case "TampaCourt":
          courtAddress = "800 East Twiggs Street, Tampa 33602";
          break;
        case "TampaCourtAnnex":
          courtAddress = "Edgecomb Courthouse entrance, 800 East Twiggs Street, Tampa 33602";
          break;
        case "PlantCityCourt":
          courtAddress = "301 North Michigan Avenue, Plant City 33563";
          break;
      }
    }
    if (data.courtDate !== "") {
      $lastCourtDate.append("<span>Court Date: <i class='text-danger'>" + data.courtDate + "</i></span><span>&nbsp;&nbsp; Court Time: <i class='text-danger'>" + data.courtTime + "</i></span><span>&nbsp;&nbsp; Court Room: <i class='text-danger'>" + data.courtRoom + "</i></span><span>&nbsp;&nbsp; Court Location: <i class='text-danger'>" + courtAddress + "</i></span>");
      $courtDateGrp.attr("hidden", false);
    } else {
      $courtDateGrp.attr("hidden", true);
    }
    $judge1.text(data.judge);
    $isD6ed.text(data.isD6ed);
    if (collectionStatus === "In Collections") {
      $pCollectionsAgencyWavName.attr("hidden", false);
    } else {
      $pCollectionsAgencyWavName.attr("hidden", true);
    }
  };
