  var handleSubmitCaseSearch = function fnSubmitCaseSearch() {
    hover.checkUser();
    var searchSecurity = setSearchByCase();
    if (searchSecurity.CaseNumber !== "") {
      var caseValidation = hover.validateCaseNumber(searchSecurity.CaseNumber);
      if (!caseValidation.validCase) {
        hover.msg.title = "Invalid Case Number";
        hover.msg.message = "Please enter a valid Case Number";
        hover.sendMessage(hover.msg);
        return;
      }
      searchSecurity.CaseNumber = caseValidation.caseNumber;
      $caseNumber.val(caseValidation.caseNumber);
    }
    if ($caseNumber.val() !== "") {
      getCaseByCaseNumber(searchSecurity);
    }
  };
  var handleUploadOrder = function fnUploadOrder() {
    $btnUploadOrder.attr("disabled", true);
    var userInfo = hover.getUserInformationModel();
    $validationMessage.html("");
    hover.msg.title = "Non Criminal Sealing Order Error";
    hover.msg.message = "";
    var caseNumber = $caseNumber.val();
    var documentDescription = $docDescription.val();
    var fileName = $FileUpload1.val();
    if (documentDescription !== "" && fileName !== "") {
      var files = $FileUpload1.get(0).files;
      var formData = new FormData();
      if (files.length > 0) {
        formData.append("UploadedImage", files[0]);
      }
      formData.append("CaseNumber", caseNumber);
      formData.append("DocumentDescription", documentDescription);
      formData.append("RequestorUserName", userInfo.UserName);
      formData.append("RequestorGuid", userInfo.RequestorGuid);
      formData.append("RequestorToken", userInfo.AccessToken);
      var ajax = dataService.nonCriminalSealingOrderUpload(formData);
      ajax.done(function(response, textStatus, xhr) {
        if (xhr.statusText === "OK" | xhr.statusText === "success") {
          loadNonCriminalSealingOrderToday(response);
          getNonCriminalSealingOrders();
          $docDescription.val("");
        } else if (xhr.statusText === "Unauthorized") {
          hover.msg.title = "Unauthorized";
          if (xhr.responseText !== "") {
            hover.msg.message = xhr.responseJSON;
          } else {
            hover.msg.message = textStatus;
          }
          hover.sendMessage(hover.msg);
        } else {
          hover.msg.title = "Upload Error";
          if (xhr.responseText !== "") {
            hover.msg.message = xhr.responseJSON;
          } else {
            hover.msg.message = textStatus;
          }
          hover.sendMessage(hover.msg);
        }
      }).fail(function(xhr, textStatus, errorThrown) {
        hover.msg.title = "Upload Error";
        if (xhr.responseText !== "") {
          hover.msg.message = xhr.responseText;
        } else {
          hover.msg.message = textStatus;
        }
        hover.sendMessage(hover.msg);
      }).always(function() {
        $btnUploadOrder.attr("disabled", false);
      });
    } else {
      hover.msg.title = "Upload Error";
      hover.msg.message = "The document description and file are required";
      hover.sendMessage(hover.msg);
    }
  };
