    var handleFileNameEntered = function fnFileNameEntered() {
      var fileName = $attorneyFileUpload.val();
      if (fileName !== null && fileName !== "" && fileName.length > 0) {
        return true;
      } else {
        hover.msg.title = "Florida Bar Error";
        hover.msg.message = "Please upload your completed On-line Registration Form";
        $ckboxAttorneyAccurate.attr("checked", false);
        $attorneyFileUpload.focus();
        hover.sendMessage(hover.msg);
        return false;
      }
    };
    var handleAttorneySubmitCkboxAccurated = function fnAttorneySubmitCkboxAccurated() {
      if ($ckboxAttorneyAccurate.is(":checked")) {
        if (handleFileNameEntered()) {
          $("#btnAttorneyRegister").prop("disabled", false);
        }
      } else {
        $("#btnAttorneyRegister").prop("disabled", true);
      }
    };
    var handleAttorneyFileUploadChange = function fnFileUploadChange() {
      $ckboxAttorneyAccurate.attr("checked", false);
      $btnAttorneyRegister.prop("disabled", false);
      $ckboxAttorneyAccurate.prop("disabled", false);
      var fileName = $attorneyFileUpload.val();
      if (fileName.length === 0) {
        $btnAttorneyRegister.prop("disabled", true);
        hover.msg.title = "Florida Bar Error";
        hover.msg.message = "Registration Form is required to continue";
        hover.sendMessage(hover.msg);
      }
      var validFileExtension = ".pdf";
      if (fileName.substr(
        fileName.length - validFileExtension.length,
        validFileExtension.length
      ).toLowerCase() !== validFileExtension.toLowerCase()) {
        $btnAttorneyRegister.prop("disabled", true);
        $ckboxAttorneyAccurate.prop("disabled", true);
        hover.msg.title = "Florida Bar Error";
        hover.msg.message = "Only PDF files are allowed";
        hover.sendMessage(hover.msg);
      }
      handleAttorneySubmitCkboxAccurated();
    };
    var handleValidateAttorneySubmitForm = function fnValidateAttorneySubmitForm() {
      var errorMessage = "";
      if ($BarNumber.val() === "") {
        errorMessage = "Bar Number is required. <br/>";
      }
      if ($FirstName.val() === "") {
        errorMessage += "First Name is required. <br/>";
      }
      if ($LastName.val() === "") {
        errorMessage += "Last Name is required. <br/>";
      }
      if ($EmailAddress.val() === "") {
        errorMessage += "Email Address is required. <br/>";
      }
      if ($attorneyFileUpload.val() === "") {
        errorMessage += "File is required. <br/>";
      }
      if ($ckboxAttorneyAccurate.is(":checked") === false) {
        errorMessage += "You must certify that the information is accurate. <br/>";
      }
      if (errorMessage === "") {
        $validationMessage.val("");
        return true;
      }
      $validationMessage.html(errorMessage);
      return true;
    };
    var handleAttorneyRegister = function fnAttorneyRegister() {
      $validationMessage.html("");
      hover.msg.title = "Florida Bar Error";
      hover.msg.message = "";
      var isValid = handleValidateAttorneySubmitForm();
      if (isValid && $EmailAddress.val() !== "" && $FirstName.val() !== "" && $LastName.val() !== "" && $attorneyFileUpload.val() !== "") {
        $btnAttorneyRegister.prop("disabled", true);
        var currentBarNumber = $BarNumber.val();
        if (currentBarNumber !== null && currentBarNumber !== "" && currentBarNumber.length > 0) {
          if (!currentBarNumber.match(/^\d+$/)) {
            hover.msg.message = "Bar number must contain only numbers.";
            hover.sendMessage(hover.msg);
            return false;
          }
        }
        var captchahash = $captchaHash.val();
        if ($ckboxAttorneyAccurate.is(":checked") === false) {
          hover.msg.message = "You must certify that the information is accurate.";
          hover.sendMessage(hover.msg);
          return false;
        }
        var files = $attorneyFileUpload.get(0).files;
        var formData = new FormData();
        if (files.length > 0) {
          formData.append("UploadedImage", files[0]);
        }
        formData.append("BarNumber", currentBarNumber);
        var ajax = dataService.attorneyInformationSubmitByBarNumber(formData);
        ajax.done(function(formData2, textStatus, xhr) {
          if (xhr.statusText === "OK" | xhr.statusText === "success") {
            window.location = "registerSubmitConfirmation.html";
          } else {
            hover.msg.title = "Registration Error";
            if (xhr.responseText !== "") {
              hover.msg.message = xhr.responseJSON;
            } else {
              hover.msg.message = textStatus;
            }
            hover.sendMessage(hover.msg);
            $captcha.val("");
            $ckboxAttorneyAccurate.prop("checked", "");
          }
        }).fail(function(xhr, textStatus, errorThrown) {
          hover.msg.title = "Registration Error";
          if (xhr.responseText !== "") {
            hover.msg.message = xhr.responseText;
          } else {
            hover.msg.message = textStatus;
          }
          hover.sendMessage(hover.msg);
          $ckboxAttorneyAccurate.prop("checked", "");
        });
      } else {
        hover.msg.title = "Registration Error";
        hover.msg.message = "Invalid Florida Bar Information";
        hover.sendMessage(hover.msg);
      }
      return false;
    };
