  var initBondsView = function fnBondsView() {
    $bondTypesdata = $("#bondTypesdata");
    $bondTypesdataTb = $("#bondTypesdata tbody");
    $messageDialog = $("#messageDialog");
    $messageDialog.load(baseWebUrl + "html/common/message.html", function(responseTxt, statusTxt, xhr) {
      if (statusTxt === "success") {
        $btnMessage = $("#btnMessage");
        $btnMessage.val("");
        $loadingDialog = $("#loadingDialog");
        loadBonds();
      }
      ;
      if (statusTxt === "error") {
        alert("Error: " + xhr.status + ": " + xhr.statusText);
      }
      ;
    });
  };
  var updateCaseCategories = function fnUpdateCaseCategories(caseCategoryTypeViewModel) {
    var userInfo = hover.getUserInformationModel();
    caseCategoryTypeViewModel.requestorUserName = userInfo.UserName;
    caseCategoryTypeViewModel.requestorGuid = userInfo.RequestorGuid;
    caseCategoryTypeViewModel.requestorToken = userInfo.AccessToken;
    var ajax = dataService.securityCaseCategoryUpdate(caseCategoryTypeViewModel);
    ajax.done(function() {
      $alerts.append('<div class="alert alert-success" role="alert">Update Success!</div>');
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).fail(function(xhr, textStatus, errorThrown) {
      $alerts.append('<div class="alert alert-danger" role="alert">Update Failure!</div>');
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).always(function() {
    });
  };
  var handleCaseCategoryTableMouseEnter = function fnHandleCaseCategoryTableMouseEnter() {
    var colIdx = table.cell(this).index().column;
    $(table.cells().nodes()).removeClass("hover");
    $(table.column(colIdx).nodes()).addClass("hover");
  };
  var handleCaseCategoryTableClickButton = function fnHandleCaseCategoryTableClickButton() {
    var caseeventTypeViewModel = table.row($(this).parents("tr")).data();
  };
  var handleCaseCategoryTableChangeInput = function fnHandleCaseCategoryTableChangeInput() {
    var caseCategoryTypeViewModel = table.row($(this).parents("tr")).data();
    var isChecked;
    if ($(this).prop("checked")) {
      isChecked = true;
    } else {
      isChecked = false;
    }
    ;
    switch ($(this)[0].name) {
      case "proactiveRedaction":
        caseCategoryTypeViewModel.proactiveRedaction = isChecked;
        break;
      default:
    }
    ;
    updateCaseCategories(caseCategoryTypeViewModel);
  };
  var handleCaseCategoryTableChangeSelect = function fnHandleCaseCategoryTableChangeSelect() {
    var caseCategoryTypeViewModel = table.row($(this).parents("tr")).data();
    var redaction = $(this).prop("value");
    var roleName = $(this)[0].name;
    var model = caseCategoryTypeViewModel;
    caseCategoryTypeViewModel = loadModel(model, roleName, redaction);
    updateCaseCategories(caseCategoryTypeViewModel);
  };
