  var initDocumentCodeView = function fnDocumentCodeView() {
    $documentCodedata = $("#documentCodesdata");
    $documentCodedataTb = $("#documentCodesdata tbody");
    $messageDialog = $("#messageDialog");
    $messageDialog.load(baseWebUrl + "html/common/message.html", function(responseTxt, statusTxt, xhr) {
      if (statusTxt === "success") {
        $btnMessage = $("#btnMessage");
        $btnMessage.val("");
        $loadingDialog = $("#loadingDialog");
        loadDocumentCode();
      }
      if (statusTxt === "error") {
        alert("Error: " + xhr.status + ": " + xhr.statusText);
      }
    });
  };
  var updateHearingTypes = function fnUpdateHearingTypes(hearingTypeViewModel) {
    var userInfo = hover.getUserInformationModel();
    hearingTypeViewModel.requestorUserName = userInfo.UserName;
    hearingTypeViewModel.requestorGuid = userInfo.RequestorGuid;
    hearingTypeViewModel.requestorToken = userInfo.AccessToken;
    var ajax = dataService.securityHearingTypeUpdate(hearingTypeViewModel);
    ajax.done(function() {
      $alerts.append('<div class="alert alert-success" role="alert">Update Success!</div>');
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).fail(function(xhr, textStatus, errorThrown) {
      $alerts.append('<div class="alert alert-danger" role="alert">Update Failure!</div>');
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).always(function() {
    });
  };
  var handleHearingTypeTableMouseEnter = function fnHandleHearingTypeTableMouseEnter() {
    var colIdx = table.cell(this).index().column;
    $(table.cells().nodes()).removeClass("hover");
    $(table.column(colIdx).nodes()).addClass("hover");
  };
  var handleHearingTypeTableClickRow = function fnHandleHearingTypeTableClickRow() {
    $(this).toggleClass("selected");
  };
  var handleHearingTypeTableClickButton = function fnHandleHearingTypeTableClickButton() {
    var hearingTypeViewModel = table.row($(this).parents("tr")).data();
  };
  var handleHearingTypeTableChangeInput = function fnHandleHearingTypeTableChangeInput() {
    var hearingTypeViewModel = table.row($(this).parents("tr")).data();
    var isChecked;
    if ($(this).prop("checked")) {
      isChecked = true;
    } else {
      isChecked = false;
    }
    switch ($(this)[0].name) {
      case "proactiveRedaction":
        hearingTypeViewModel.proactiveRedaction = isChecked;
        break;
      default:
    }
    updateHearingTypes(hearingTypeViewModel);
  };
  var handleHearingTypeTableChangeSelect = function fnHandleHearingTypeTableChangeSelect() {
    var hearingTypeViewModel = table.row($(this).parents("tr")).data();
    var redaction = $(this).prop("value");
    var roleName = $(this)[0].name;
    var model = hearingTypeViewModel;
    hearingTypeViewModel = loadModel(model, roleName, redaction);
    updateHearingTypes(hearingTypeViewModel);
  };
