          securityHearingTypeModel.requestorUserName = userInfo.UserName;
          securityHearingTypeModel.requestorGuid = userInfo.RequestorGuid;
          loadHearingEventsTypes(securityHearingTypeModel);
          return JSON.stringify(d);
