  function updateJudgmentSelections(httpResponseArray) {
    var overriden = [];
    var idx = 0;
    var currentEventSecurity;
    lazyProduct.cartesianProduct([[5], selectedCaseTypesRows, selectedJudgmentEventTypesRows, selectedDocumentCodeRows, selectedSecurityRole(), selectedSecurityFlag()], function(n, selectedCaseTypeRow, selectedJudgmentEventTypeRow, selectedDocumentCodeRow, selectedSecurityRoleRow, selectedSecurityFlagRow) {
      var selectedCaseType = selectedCaseTypeRow.caseType.toString();
      var selectedJudgmentEventType = selectedJudgmentEventTypeRow.code.toString();
      var selectedDocumentCode = selectedDocumentCodeRow.code.toString();
      currentEventSecurity = getCurrentEventSecurity(selectedCaseTypeRow, selectedJudgmentEventTypeRow);
      var existingOverride = "";
      for (var index = 0; index < httpResponseArray.length; index++) {
        if (httpResponseArray[index].caseType === selectedCaseType && httpResponseArray[index].judgmentEventCode === selectedJudgmentEventType && httpResponseArray[index].documentCode === selectedDocumentCode && httpResponseArray[index].role === selectedSecurityRoleRow.toString()) {
          existingOverride = httpResponseArray[index].documentAccessLevel;
        }
      }
      if (idx < 1e3) {
        overriden.push(
          {
            "CaseType": selectedCaseType,
            "JudgmentEventType": selectedJudgmentEventType,
            "CaseTypeDescription": selectedCaseTypeRow.caseTypeDescription,
            "JudgmentEventTypeDescription": selectedJudgmentEventTypeRow.description,
            "DocumentCodeDescription": selectedDocumentCodeRow.description,
            //"Admin": currentEventSecurity.Admin,
            "Manager": currentEventSecurity.Manager,
            "Clerk": currentEventSecurity.Clerk,
            "Attorney": currentEventSecurity.Attorney,
            "AttorneyOfRecord": currentEventSecurity.AttorneyOfRecord,
            "Prose": currentEventSecurity.Prose,
            "RegisteredUser": currentEventSecurity.RegisteredUser,
            "PublicView": currentEventSecurity.PublicView,
            "GeneralPublic": currentEventSecurity.GeneralPublic,
            "CCISPub": currentEventSecurity.CCISPub,
            "CCISConf": currentEventSecurity.CCISConf,
            "ConstitutionalOfficer": currentEventSecurity.ConstitutionalOfficer,
            "AttorneyGeneral": currentEventSecurity.AttorneyGeneral,
            "CommercialPurchaser": currentEventSecurity.CommercialPurchaser,
            "DeptChildrenFamilies": currentEventSecurity.DeptChildrenFamilies,
            "GeneralGovernment": currentEventSecurity.GeneralGovernment,
            "JudicialAssistant": currentEventSecurity.JudicialAssistant,
            "LawEnforcement": currentEventSecurity.LawEnforcement,
            "PartyOnCase": currentEventSecurity.PartyOnCase,
            "SchoolBoard": currentEventSecurity.SchoolBoard,
            "StateAttorney": currentEventSecurity.StateAttorney,
            "Judge": currentEventSecurity.Judge,
            "GuardianAdLitem": currentEventSecurity.GuardianAdLitem,
            "PublicDefender": currentEventSecurity.PublicDefender,
            "SW": currentEventSecurity.SW,
            "RegionalCounsel": currentEventSecurity.RegionalCounsel,
            "AnonymousUser": currentEventSecurity.AnonymousUser,
            "ClerkAnonymousUserEcertify": currentEventSecurity.ClerkAnonymousUserEcertify,
            "RegisteredUserProse": currentEventSecurity.RegisteredUserProse,
            "TaxCollector": currentEventSecurity.TaxCollector,
            "JusticeAdminCommission": currentEventSecurity.JusticeAdminCommission,
            "Role": selectedSecurityRoleRow,
            "Flag": selectedSecurityFlagRow,
            "ExistingOverride": existingOverride
          }
        );
      }
      idx++;
    });
    if (overriden.length > 0) {
      $overridenCodes.show();
      $submitOverride.show();
      loadOverridenJudgmentTable(overriden);
    } else {
      $submitOverride.hide();
      $overridenCodes.hide();
    }
  }
  function loadOverridenJudgmentTypesValidation() {
    var overrideSecurityJudgmentEventType = {
      CaseCategory: $selectedCaseCategories.val(),
      CaseType: selectedCaseTypesKeys.toString(),
      CaseTypeCode: "",
      JudgmentEventCode: selectedJudgmentEventTypesKeys.toString(),
      DocumentCode: selectedDocumentCodeKeys.toString(),
      Role: selectedSecurityRole().toString(),
      DocumentAccessLevel: selectedSecurityFlag(),
      EnableOverride: ""
    };
    var ajax = dataService.securityJudgmentEventTypeValidate(overrideSecurityJudgmentEventType);
    ajax.done(function(httpResponse) {
      updateJudgmentSelections(httpResponse);
    }).fail(function(xhr, textStatus, errorThrown) {
      alert(errorThrown);
      $alerts.append("<div class='alert alert-danger' role='alert'>Validation Failure!</div>");
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).always(function() {
    });
  }
  function insertOverrideJudgmentTypes(overrideSecurityJudgmentEventType) {
    var ajax = dataService.securityJudgmentEventTypeInsert(overrideSecurityJudgmentEventType);
    ajax.done(function() {
      clearCheckboxAllCaseTypes();
      clearCheckboxAllJudgmentEventsTypes();
      clearCheckboxAllDocumentCodes();
      $submitOverride.hide();
      $overridenCodes.hide();
      hover.msg.title = "Judgment Event Override";
      hover.msg.message = "Override Accepted";
      hover.msg.redirect = "";
      hover.sendMessage(hover.msg);
    }).fail(function(xhr, textStatus, errorThrown) {
      alert(errorThrown);
      $alerts.append("<div class='alert alert-danger' role='alert'>Update Failure!</div>");
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).always(function() {
    });
  }
  function overrideJudgmentEvents() {
    var userInfo = hover.getUserInformationModel();
    var overrideSecurityJudgmentEventType = {
      CaseCategory: $selectedCaseCategories.val(),
      CaseType: selectedCaseTypesKeys.toString(),
      CaseTypeCode: "",
      JudgmentEventCode: selectedJudgmentEventTypesKeys.toString(),
      DocumentCode: selectedDocumentCodeKeys.toString(),
      Role: selectedSecurityRole().toString(),
      DocumentAccessLevel: selectedSecurityFlag(),
      EnableOverride: ""
    };
    overrideSecurityJudgmentEventType.requestorUserName = userInfo.UserName;
    overrideSecurityJudgmentEventType.requestorGuid = userInfo.RequestorGuid;
    overrideSecurityJudgmentEventType.requestorToken = userInfo.AccessToken;
    insertOverrideJudgmentTypes(overrideSecurityJudgmentEventType);
  }
  var loadWarrantEventsTypes = function fnLoadWarrantEventsTypes(securityWarrantEventTypeModel) {
    var ajax = dataService.securityWarrantEventTypeGetKeys(securityWarrantEventTypeModel);
    ajax.done(function(httpResponse) {
      warrantEventTypesKeys = [];
      selectedWarrantEventTypesKeys = [];
      selectedWarrantEventTypesRows = [];
      for (var i = 0; i < httpResponse.length; i++) {
        warrantEventTypesKeys.push(httpResponse[i].caseType);
      }
      if ($warrantEventTypesCheckAll.is(":checked")) {
        selectedWarrantEventTypesKeys = warrantEventTypesKeys;
        selectedWarrantEventTypesRows = httpResponse;
      }
    }).fail(function(xhr, textStatus, errorThrown) {
      alert(errorThrown);
      $alerts.append('<div class="alert alert-danger" role="alert">Load Drop Down case types Failure!</div>');
      $(".alert").delay(100).addClass("in").fadeOut(2e3);
    }).always(function() {
    });
  };
  var handleWarrantEventsTypesTableTbUnbindChange = function fnWarrantEventsTypesTableTbUnbindChange() {
    $warrantEventTypesCheckAll.prop("checked", false);
    var warrantEventTypeViewModel = warrantEventTypesTable.row($(this).parents("tr")).data();
    var warrantEventTypeCode = warrantEventTypeViewModel.code;
    var index = $.inArray(warrantEventTypeCode, selectedWarrantEventTypesKeys);
    if (index === -1) {
      selectedWarrantEventTypesKeys.push(warrantEventTypeCode);
      selectedWarrantEventTypesRows.push(warrantEventTypeViewModel);
    } else {
      selectedWarrantEventTypesKeys.splice(index, 1);
      selectedWarrantEventTypesRows.splice(index, 1);
    }
    if ($(this).prop("checked")) {
      $(this).parents("tr").addClass("selected");
    } else {
      $(this).parents("tr").removeClass("selected");
    }
    $overridenCodes.hide();
    $submitOverride.hide();
  };
  var loadWarrantEventsTypesTable = function fnLoadWarrantEventsTypesTable(category) {
    var userInfo = hover.getUserInformationModel();
    warrantEventTypesTable = $warrantEventTypesTable.DataTable({
      language: {
        paginate: {
          previous: "Previous page",
          next: "Next page",
          first: "First page",
          last: "Last page"
        },
        aria: {
          paginate: {
            previous: "Previous Page",
            next: "Next Page",
            first: "First Page",
            last: "Last Page"
          }
        },
        processing: '<img src="https://hover.hillsclerk.com/images/loading2.gif" class="img-fluid" alt="loading">'
      },
      order: [[0, "asc"]],
      lengthMenu: [[10, 50, 100, 250, 500, 1e3 - 1], [10, 50, 100, 250, 500, 1e3, "All"]],
      destroy: true,
      searching: true,
      processing: true,
      fixedHeader: {
        headerOffset: 50
      },
      scrollX: false,
      stateSave: true,
      info: true,
      dom: "<'row'<'col-sm-6'l><'col-sm-6'f>><'row'<'col-sm-12'tr>><'row'<'col-sm-12'i>><'row'<'col-sm-12'p>>",
      serverSide: true,
      ajax: {
        url: baseWebUrl + "SecurityWarrantType/GetByCategory",
        data: function(d) {
          d.category = category;
          securityWarrantTypeModel.Category = category;
          securityWarrantTypeModel.Search = d.search.value;
          securityWarrantTypeModel.requestorUserName = userInfo.UserName;
          securityWarrantTypeModel.requestorGuid = userInfo.RequestorGuid;
          loadWarrantEventsTypes(securityWarrantTypeModel);
          return JSON.stringify(d);
        },
        type: "POST",
        crossDomain: true,
        dataType: "json",
        contentType: "application/json",
        async: true,
        headers: hover.authHeader(),
        error: function(xhr, textStatus, errorThrown) {
          if (xhr.statusText === "Unauthorized") {
            alert(errorThrown);
            window.location.href = "/html/account/login.html";
          } else {
            alert(errorThrown);
            $alerts.append("<div class='alert alert-danger' role='alert'>Update Failure!</div>");
            $(".alert").delay(100).addClass("in").fadeOut(2e3);
          }
        },
        complete: function() {
        }
      },
      columns: [
        { data: "code" },
        {
          data: "description",
          mRender: function(data, type, row) {
            if (row.description) {
              return row.description;
            }
            return "";
          }
        },
        {
          visible: true,
          bSortable: false,
          sClass: "text-center dt-head-center dt-body-center",
          mRender: function(data, type, row) {
            if ($.inArray(row.caseType, selectedWarrantEventTypesKeys) !== -1) {
              return '<input type="checkbox" checked name="selectedCaseType" value="true">';
            } else {
              return '<input type="checkbox" name="selectedCaseType" value="false">';
            }
          }
        }
      ],
      rowCallback: function(row, data) {
        if ($.inArray(data.caseType, selectedWarrantEventTypesKeys) !== -1) {
          $(row).addClass("selected");
          return '<input type="checkbox" checked name="selectedCaseType" value="true">';
        } else {
          return '<input type="checkbox" name="selectedCaseType" value="false">';
        }
      }
    });
    $warrantEventTypesTableTb.unbind("change").on("change", "input", handleWarrantEventsTypesTableTbUnbindChange);
  };
  var handleCheckboxAllWarrantEventsTypesCheck = function fnCheckboxAllWarrantEventsTypesCheck() {
    var selectedCategory = $selectedCaseCategories.val();
    if ($warrantEventTypesCheckAll.is(":checked")) {
      selectedWarrantEventTypesKeys = warrantEventTypesKeys;
      loadWarrantEventsTypesTable(selectedCategory);
    } else {
      clearCheckboxAllWarrantEventsTypes();
    }
  };
  function clearCheckboxAllWarrantEventsTypes() {
    var selectedCategory = $selectedCaseCategories.val();
    selectedWarrantEventTypesKeys = [];
    selectedWarrantEventTypesRows = [];
    $warrantEventTypesCheckAll.prop("checked", false);
    if (warrantEventTypesTable) {
      warrantEventTypesTable.state.clear();
    }
    loadWarrantEventsTypesTable(selectedCategory);
  }
